import{_ as n}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{L as l,x as r,A as i,G as a,M as d,Z as o,B as A}from"./chunks/runtime-core.esm-bundler.BPWg86ya.js";const g="/assets/agent-vs-app.ClJQcFcA.jpg",f=JSON.parse('{"title":"AI Agent 工程与 AI 应用开发的区别：从概念到技术架构","description":"","frontmatter":{},"headers":[],"relativePath":"column/AIFuture/基础认知/AI Agent工程与AI应用开发区别.md","filePath":"column/AIFuture/基础认知/AI Agent工程与AI应用开发区别.md","lastUpdated":1792032026000}'),h={name:"column/AIFuture/基础认知/AI Agent工程与AI应用开发区别.md"};function p(s,t,I,c,u,b){const e=l("ArticleMetadata");return i(),r("div",null,[t[0]||(t[0]=a("h1",{id:"ai-agent-工程与-ai-应用开发的区别-从概念到技术架构",tabindex:"-1"},[A("AI Agent 工程与 AI 应用开发的区别：从概念到技术架构 "),a("a",{class:"header-anchor",href:"#ai-agent-工程与-ai-应用开发的区别-从概念到技术架构","aria-label":'Permalink to "AI Agent 工程与 AI 应用开发的区别：从概念到技术架构"'},"​")],-1)),d(e),t[1]||(t[1]=o('<nav class="table-of-contents"><ul><li><a href="#一、什么是-ai-应用开发与-ai-agent-工程">一、什么是 AI 应用开发与 AI Agent 工程？</a><ul><li><a href="#_1-1-ai-应用开发">1.1 AI 应用开发</a></li><li><a href="#_1-2-ai-agent-工程">1.2 AI Agent 工程</a></li></ul></li><li><a href="#二、ai-应用开发与-ai-agent-工程的核心区别">二、AI 应用开发与 AI Agent 工程的核心区别</a></li><li><a href="#三、从技术架构理解两者的区别">三、从技术架构理解两者的区别</a><ul><li><a href="#_3-1-ai-应用开发的典型架构">3.1 AI 应用开发的典型架构</a></li><li><a href="#_3-2-ai-agent-工程的典型架构">3.2 AI Agent 工程的典型架构</a></li></ul></li><li><a href="#四、langchain、langgraph-与-vercel-ai-sdk-有什么区别">四、LangChain、LangGraph 与 Vercel AI SDK 有什么区别？</a><ul><li><a href="#_4-1-vercel-ai-sdk-构建-ai-应用">4.1 Vercel AI SDK：构建 AI 应用</a></li><li><a href="#_4-2-langchain-构建-llm-应用与-agent">4.2 LangChain：构建 LLM 应用与 Agent</a></li><li><a href="#_4-3-langgraph-编排有状态的-agent-工作流">4.3 LangGraph：编排有状态的 Agent 工作流</a></li></ul></li><li><a href="#五、实际项目应该如何选择">五、实际项目应该如何选择？</a></li><li><a href="#六、学习路线-从-ai-应用开发到-agent-工程">六、学习路线：从 AI 应用开发到 Agent 工程</a><ul><li><a href="#_01-ai-应用基础">01 AI 应用基础</a></li><li><a href="#_02-完整-ai-产品">02 完整 AI 产品</a></li><li><a href="#_03-agent-核心机制">03 Agent 核心机制</a></li><li><a href="#_04-agent-工程化">04 Agent 工程化</a></li><li><a href="#_05-生产级实践">05 生产级实践</a></li></ul></li><li><a href="#七、总结">七、总结</a></li></ul></nav><p><img src="'+g+'" alt="" loading="lazy"></p><p>随着大语言模型的发展，AI 开发逐渐从简单的模型调用，发展到完整的 AI 产品构建，以及能够自主规划、调用工具和执行复杂任务的智能 Agent 系统。</p><p>在学习 AI 技术时，经常会遇到两个概念：<strong>AI 应用开发（AI Application Development）</strong> 和 <strong>AI Agent 工程（AI Agent Engineering）</strong>。</p><p>下面介绍两者的关系：</p><h2 id="一、什么是-ai-应用开发与-ai-agent-工程" tabindex="-1">一、什么是 AI 应用开发与 AI Agent 工程？ <a class="header-anchor" href="#一、什么是-ai-应用开发与-ai-agent-工程" aria-label="Permalink to &quot;一、什么是 AI 应用开发与 AI Agent 工程？&quot;">​</a></h2><h3 id="_1-1-ai-应用开发" tabindex="-1">1.1 AI 应用开发 <a class="header-anchor" href="#_1-1-ai-应用开发" aria-label="Permalink to &quot;1.1 AI 应用开发&quot;">​</a></h3><p>AI 应用开发是指将大语言模型、机器学习模型等 AI 能力集成到实际的软件产品中，为用户提供具体的业务功能。</p><p>例如：</p><ul><li><strong>AI 聊天助手</strong>：支持多轮对话、流式输出和历史消息。</li><li><strong>AI 文档问答</strong>：上传 <code>PDF</code> 或 <code>Word</code> 文档，通过 <code>RAG</code> 实现知识库问答。</li><li><strong>AI 写作工具</strong>：根据用户输入生成文章、摘要和营销文案。</li><li><strong>AI 编程助手</strong>：分析代码、解释错误、生成代码片段。</li><li><strong>企业 AI 平台</strong>：集成模型服务、用户权限、知识库和业务系统。</li></ul><p>AI 应用开发关注的不仅是模型能否生成正确答案，还包括产品交互、业务逻辑、数据管理、安全控制、部署运维等完整的软件工程问题。</p><blockquote><p>其核心目标是：<strong>将 AI 能力转化为稳定、可用、可维护的产品功能。</strong></p></blockquote><h3 id="_1-2-ai-agent-工程" tabindex="-1">1.2 AI Agent 工程 <a class="header-anchor" href="#_1-2-ai-agent-工程" aria-label="Permalink to &quot;1.2 AI Agent 工程&quot;">​</a></h3><p><code>AI Agent</code> 工程关注如何构建能够围绕目标进行推理、规划、调用工具、维护执行状态，并根据中间结果调整行动的智能系统。</p><p>传统 AI 应用通常由开发者明确编排主要处理流程，而 Agent 可以在一定的权限和约束范围内，根据任务目标与执行结果动态选择下一步行动。</p><p>例如，用户提出需求：</p><blockquote><p>帮我分析上个月的项目进度，找出延期项目，查询负责人，并生成一份汇总报告。</p></blockquote><p>一个具备 Agent 能力的系统可以执行以下操作：</p><ol><li>理解用户目标，识别需要分析的时间范围。</li><li>调用项目管理系统，查询上个月的项目数据。</li><li>分析项目进度，识别延期项目。</li><li>调用业务接口，查询项目负责人。</li><li>检查数据是否完整，必要时继续查询。</li><li>汇总分析结果，生成报告。</li></ol><p>这里的关键是，系统不只是生成一段文字，而是需要协调模型、工具、业务数据和执行流程，最终完成一个包含多个步骤的任务。</p><blockquote><p>其核心目标是：<strong>让 AI 从回答问题进一步发展到在受控范围内执行任务。</strong></p></blockquote><h2 id="二、ai-应用开发与-ai-agent-工程的核心区别" tabindex="-1">二、AI 应用开发与 AI Agent 工程的核心区别 <a class="header-anchor" href="#二、ai-应用开发与-ai-agent-工程的核心区别" aria-label="Permalink to &quot;二、AI 应用开发与 AI Agent 工程的核心区别&quot;">​</a></h2><p>两者并不是完全独立的领域。AI Agent 工程通常需要依赖 AI 应用开发的基础设施，而 AI 应用也可以集成 Agent 能力。</p><table tabindex="0"><thead><tr><th>对比维度</th><th>AI 应用开发</th><th>AI Agent 工程</th></tr></thead><tbody><tr><td>核心目标</td><td>将 AI 能力做成完整产品</td><td>让 AI 执行复杂任务</td></tr><tr><td>关注重点</td><td>产品功能、交互、业务集成</td><td>推理、规划、工具调用、状态编排</td></tr><tr><td>典型模式</td><td>请求模型并返回结果</td><td>观察结果、决定行动、继续执行</td></tr><tr><td>执行流程</td><td>可以是固定流程，也可以包含动态逻辑</td><td>通常具有一定的动态决策能力</td></tr><tr><td>核心技术</td><td>API、Streaming、数据库、RAG、认证</td><td>Tools、Agent Loop、状态图、Checkpoint</td></tr><tr><td>工程难点</td><td>用户体验、安全、稳定性、可维护性</td><td>执行可靠性、异常恢复、状态一致性</td></tr><tr><td>典型框架</td><td>Vercel AI SDK 等</td><td>LangChain、LangGraph 等</td></tr><tr><td>典型成果</td><td>AI 聊天应用、知识库、AI 写作工具</td><td>自动化分析 Agent、任务执行 Agent</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">需要特别注意</p><p><strong>多步骤工作流不一定就是 Agent。</strong> 如果执行步骤、顺序和分支都由开发者预先确定，它更接近传统工作流；如果模型能够根据任务目标和执行结果动态决定下一步行动，则更符合 Agent 的典型特征。</p></div><h2 id="三、从技术架构理解两者的区别" tabindex="-1">三、从技术架构理解两者的区别 <a class="header-anchor" href="#三、从技术架构理解两者的区别" aria-label="Permalink to &quot;三、从技术架构理解两者的区别&quot;">​</a></h2><h3 id="_3-1-ai-应用开发的典型架构" tabindex="-1">3.1 AI 应用开发的典型架构 <a class="header-anchor" href="#_3-1-ai-应用开发的典型架构" aria-label="Permalink to &quot;3.1 AI 应用开发的典型架构&quot;">​</a></h3><p>一个基于 Next.js 的 AI 聊天应用，可以采用以下分层架构：</p><table tabindex="0"><thead><tr><th>层级</th><th>组成</th></tr></thead><tbody><tr><td>前端交互层</td><td>React · 聊天 UI · Markdown · 消息状态</td></tr><tr><td>应用服务层</td><td>Next.js API · 用户认证 · 会话管理 · 权限校验</td></tr><tr><td>AI 能力层</td><td>模型调用 · Prompt 组装 · Streaming · RAG</td></tr><tr><td>数据与基础设施</td><td>数据库 · 文件存储 · 向量检索 · 日志与监控</td></tr></tbody></table><p>用户发送消息后，应用服务层完成身份验证和业务处理，再调用大模型，将结果通过流式响应返回前端。</p><p>在这个过程中，开发者需要重点解决：</p><ul><li>如何组织 Prompt 和上下文。</li><li>如何实现流式输出和多轮对话。</li><li>如何保存会话与历史消息。</li><li>如何进行用户认证、权限控制和请求限流。</li><li>如何处理模型超时、调用失败和成本控制。</li></ul><p>即使应用只有一次模型调用，也完全属于 AI 应用开发。</p><h3 id="_3-2-ai-agent-工程的典型架构" tabindex="-1">3.2 AI Agent 工程的典型架构 <a class="header-anchor" href="#_3-2-ai-agent-工程的典型架构" aria-label="Permalink to &quot;3.2 AI Agent 工程的典型架构&quot;">​</a></h3><p>在 AI 应用的基础上，如果需要执行更复杂的任务，可以引入 Agent 运行机制。</p><table tabindex="0"><thead><tr><th>阶段</th><th>说明</th></tr></thead><tbody><tr><td>用户目标</td><td>输入任务与约束条件</td></tr><tr><td>Agent 决策</td><td>理解目标、选择工具、决定下一步行动</td></tr><tr><td>工具执行</td><td>调用 API、查询数据库、检索知识库</td></tr><tr><td>状态更新与结果检查</td><td>记录执行结果、检查条件、处理异常；根据结果继续决策，或结束任务</td></tr><tr><td>任务完成</td><td>返回结果、生成报告或等待人工审批</td></tr></tbody></table><p>Agent 的运行过程通常包含决策与执行循环：</p><ol><li>接收目标与当前状态。</li><li>根据上下文选择下一步行动。</li><li>调用工具并获取执行结果。</li><li>将结果更新到当前状态。</li><li>判断继续执行、请求人工介入，还是结束任务。</li></ol><div class="tip custom-block"><p class="custom-block-title">工程约束不可省略</p><p>在实际工程中，这个循环必须受到明确约束，例如<strong>最大执行步数、工具权限、超时限制和异常处理策略</strong>。不能让 Agent 无限循环，也不能允许它无条件执行高风险操作。</p></div><h2 id="四、langchain、langgraph-与-vercel-ai-sdk-有什么区别" tabindex="-1">四、LangChain、LangGraph 与 Vercel AI SDK 有什么区别？ <a class="header-anchor" href="#四、langchain、langgraph-与-vercel-ai-sdk-有什么区别" aria-label="Permalink to &quot;四、LangChain、LangGraph 与 Vercel AI SDK 有什么区别？&quot;">​</a></h2><p>这三个技术经常出现在 AI 项目中，但它们的定位并不完全相同。</p><h3 id="_4-1-vercel-ai-sdk-构建-ai-应用" tabindex="-1">4.1 Vercel AI SDK：构建 AI 应用 <a class="header-anchor" href="#_4-1-vercel-ai-sdk-构建-ai-应用" aria-label="Permalink to &quot;4.1 Vercel AI SDK：构建 AI 应用&quot;">​</a></h3><p>Vercel AI SDK 面向 TypeScript 生态，适合与 React、Next.js 等技术结合，用于构建 AI 应用。</p><p>主要应用场景包括：</p><ul><li>接入不同的大模型服务。</li><li>构建聊天界面与多轮对话。</li><li>实现流式文本和结构化数据输出。</li><li>管理前端消息状态。</li><li>将 AI 能力集成到现有 Web 产品中。</li></ul><p>如果目标是快速开发一个完整的 AI 聊天应用，Vercel AI SDK 是值得优先学习的工具。</p><h3 id="_4-2-langchain-构建-llm-应用与-agent" tabindex="-1">4.2 LangChain：构建 LLM 应用与 Agent <a class="header-anchor" href="#_4-2-langchain-构建-llm-应用与-agent" aria-label="Permalink to &quot;4.2 LangChain：构建 LLM 应用与 Agent&quot;">​</a></h3><p>LangChain 提供模型、工具、检索等组件，并支持构建 Agent。</p><p>主要应用场景包括：</p><ul><li>模型与工具集成。</li><li>文档检索和 RAG。</li><li>结构化输出。</li><li>Agent 构建。</li><li>将多个 AI 能力组合成应用流程。</li></ul><p>它适合希望使用较高层次抽象快速开发 LLM 应用与 Agent 的开发者。</p><h3 id="_4-3-langgraph-编排有状态的-agent-工作流" tabindex="-1">4.3 LangGraph：编排有状态的 Agent 工作流 <a class="header-anchor" href="#_4-3-langgraph-编排有状态的-agent-工作流" aria-label="Permalink to &quot;4.3 LangGraph：编排有状态的 Agent 工作流&quot;">​</a></h3><p>LangGraph 更侧重有状态、可持续运行的 Agent 系统与复杂工作流编排。</p><p>它可以将任务拆分为节点和边，通过状态传递与条件路由控制执行过程。</p><p>主要应用场景包括：</p><ul><li>多步骤任务编排。</li><li>条件分支与循环执行。</li><li>状态持久化与 Checkpoint。</li><li>暂停执行、人工审批和恢复。</li><li>需要较强可控性的 Agent 系统。</li></ul><p>简单来说，可以这样理解：</p><table tabindex="0"><thead><tr><th>技术</th><th>主要定位</th><th>典型用途</th></tr></thead><tbody><tr><td>Vercel AI SDK</td><td>AI 应用开发工具集</td><td>Web 聊天、模型接入、流式输出</td></tr><tr><td>LangChain</td><td>LLM 应用与 Agent 框架</td><td>模型、工具、检索、Agent</td></tr><tr><td>LangGraph</td><td>有状态的流程编排运行时</td><td>复杂 Agent、状态管理、暂停与恢复</td></tr></tbody></table><p>这些技术可以组合使用，并非互相排斥。例如，Next.js 负责产品界面和应用服务，Vercel AI SDK 负责聊天交互，而 LangGraph 负责复杂的 Agent 执行流程。</p><p>但并非每个项目都需要同时引入它们。对于简单的 AI 聊天应用，直接调用模型即可；只有在流程复杂度和可靠性要求确实需要时，再引入 Agent 框架。</p><h2 id="五、实际项目应该如何选择" tabindex="-1">五、实际项目应该如何选择？ <a class="header-anchor" href="#五、实际项目应该如何选择" aria-label="Permalink to &quot;五、实际项目应该如何选择？&quot;">​</a></h2><p>假设要开发一个企业 AI 助手，可以根据业务需求逐步选择架构。</p><table tabindex="0"><thead><tr><th>项目需求</th><th>建议方案</th></tr></thead><tbody><tr><td>普通 AI 聊天</td><td>Next.js + 模型 API 或 Vercel AI SDK</td></tr><tr><td>聊天历史与多用户系统</td><td>AI 应用 + 数据库 + 身份认证</td></tr><tr><td>企业知识库问答</td><td>AI 应用 + RAG + 权限过滤</td></tr><tr><td>自动查询业务数据并生成报告</td><td>AI 应用 + Agent + 业务工具</td></tr><tr><td>多步骤任务、条件分支、人工审批</td><td>根据复杂度引入 LangGraph</td></tr><tr><td>长时间运行、需要恢复的 Agent 任务</td><td>LangGraph + 状态持久化 + 任务监控</td></tr></tbody></table><p>以企业项目管理助手为例，可以分阶段建设：</p><p><strong>第一阶段：AI 应用。</strong> 用户输入问题，系统查询项目数据并生成回答，支持会话保存和历史记录。</p><p><strong>第二阶段：工具调用。</strong> 为 AI 提供项目查询、负责人查询、进度统计等经过权限校验的工具。</p><p><strong>第三阶段：Agent 执行。</strong> 允许模型根据用户目标选择工具，组合查询结果，完成多步骤分析。</p><p><strong>第四阶段：工程化。</strong> 加入执行状态持久化、失败重试、人工审批、日志追踪、成本统计与效果评估。</p><p>这种渐进式路线可以避免在简单需求中引入过多复杂度，同时为后续扩展保留空间。</p><h2 id="六、学习路线-从-ai-应用开发到-agent-工程" tabindex="-1">六、学习路线：从 AI 应用开发到 Agent 工程 <a class="header-anchor" href="#六、学习路线-从-ai-应用开发到-agent-工程" aria-label="Permalink to &quot;六、学习路线：从 AI 应用开发到 Agent 工程&quot;">​</a></h2><p>对于已经具备前端和后端开发基础的开发者，可以按照以下顺序学习。</p><h3 id="_01-ai-应用基础" tabindex="-1">01 AI 应用基础 <a class="header-anchor" href="#_01-ai-应用基础" aria-label="Permalink to &quot;01 AI 应用基础&quot;">​</a></h3><p>大模型 API、Prompt、Streaming、SSE、聊天 UI。</p><p><strong>目标</strong>：构建可交互的 AI 聊天应用。</p><h3 id="_02-完整-ai-产品" tabindex="-1">02 完整 AI 产品 <a class="header-anchor" href="#_02-完整-ai-产品" aria-label="Permalink to &quot;02 完整 AI 产品&quot;">​</a></h3><p>数据库、会话管理、用户认证、RAG、部署与监控。</p><p><strong>目标</strong>：让 AI 应用具备真实业务使用能力。</p><h3 id="_03-agent-核心机制" tabindex="-1">03 Agent 核心机制 <a class="header-anchor" href="#_03-agent-核心机制" aria-label="Permalink to &quot;03 Agent 核心机制&quot;">​</a></h3><p>Function Calling、Tools、Agent Loop、上下文与记忆。</p><p><strong>目标</strong>：让 AI 能够调用业务工具完成任务。</p><h3 id="_04-agent-工程化" tabindex="-1">04 Agent 工程化 <a class="header-anchor" href="#_04-agent-工程化" aria-label="Permalink to &quot;04 Agent 工程化&quot;">​</a></h3><p>LangChain、LangGraph、Checkpoint、人工审批、异常恢复。</p><p><strong>目标</strong>：构建可控、可靠、可观测的 Agent 系统。</p><h3 id="_05-生产级实践" tabindex="-1">05 生产级实践 <a class="header-anchor" href="#_05-生产级实践" aria-label="Permalink to &quot;05 生产级实践&quot;">​</a></h3><p>评估体系、权限边界、成本优化、工具安全、多 Agent 协作。</p><p><strong>目标</strong>：将 Agent 从演示原型推进到可维护的业务系统。</p><h2 id="七、总结" tabindex="-1">七、总结 <a class="header-anchor" href="#七、总结" aria-label="Permalink to &quot;七、总结&quot;">​</a></h2><p>AI 应用开发与 AI Agent 工程的主要区别，在于解决问题的层次不同。</p><ul><li><strong>AI 应用开发</strong>：关注如何把模型能力集成到产品中，解决交互、数据、权限、部署等完整的软件工程问题。</li><li><strong>AI Agent 工程</strong>：关注如何让 AI 在受控环境下进行决策、调用工具、管理状态，并完成多步骤任务。</li><li><strong>两者的关系</strong>：AI Agent 可以作为 AI 应用中的一个能力模块。一个成熟的 Agent 产品，通常也需要完整的应用开发基础设施。</li></ul><p>如果以 TypeScript 和 Next.js 为主要技术栈，建议先掌握 AI 应用开发，再学习 Agent 的工具调用和运行机制，最后深入 LangGraph 的状态管理与流程编排。</p><p>真正有价值的 AI 工程能力，不仅是让模型生成答案，更是让整个系统能够安全、稳定、可验证地解决实际问题。</p>',91))])}const q=n(h,[["render",p]]);export{f as __pageData,q as default};
